import React from 'react';
import { ColorNameEnum, SizeEnum, Text, WeightEnum } from '@getvim/atomic-ui';
import classNames from 'classnames';
import RedUser from '../../assets/red-user.svg';
import './index.less';

interface MissingInformationContainerProps {
  noInformationRequired?: boolean;
  children: JSX.Element;
}

export const MissingInformationContainer = ({
  noInformationRequired,
  children,
}: MissingInformationContainerProps) => {
  return (
    <div
      className={classNames(
        'user-center-missing-information-container',
        noInformationRequired && 'hidden',
      )}
    >
      {!noInformationRequired && (
        <div className="cta-text">
          <img src={RedUser} />
          <Text
            text={'Please choose your role to personalize your experience.'}
            size={SizeEnum['14px']}
            colorName={ColorNameEnum.extraDark}
            weight={WeightEnum.semibold}
          />
        </div>
      )}
      {children}
    </div>
  );
};
